   605→            el.style.opacity  = '1';
   606→            el.style.transform = 'translateY(0)';
   607→            // Count-up for numeric feature stats
   608→            var numEl = el.querySelector('.feature-num');
   609→            if (!numEl) return;
   610→            var rawText = numEl.textContent.trim();
   611→            var numMatch = rawText.match(/^([\d,.]+)/);
   612→            if (!numMatch) return; // skip non-numeric (e.g. "Rp100M+", "24/7")
   613→            var target = parseInt(numMatch[1].replace(/[,.]/g, ''), 10);
   614→            if (!target || target < 2) return;
   615→            var suffix = rawText.replace(numMatch[0], '');
   616→            var duration = 900;
   617→            var startTime = null;
   618→            numEl.textContent = '0' + suffix;
   619→            function step(ts) {
   620→                if (!startTime) startTime = ts;
   621→                var progress = Math.min((ts - startTime) / duration, 1);
   622→                var ease = 1 - Math.pow(1 - progress, 3);
   623→                numEl.textContent = Math.round(ease * target).toLocaleString('id') + suffix;
   624→                if (progress < 1) requestAnimationFrame(step);
   625→            }
   626→            requestAnimationFrame(step);
   627→        }, 350 + i * 60);
   628→    });
