    89→    public function submit(Request $request, Tryout $tryout)
    90→    {
    91→        $student = $this->getStudent();
    92→        if (!$student) abort(403);
    93→
    94→        $attempt = TryoutAttempt::where('tryout_id', $tryout->id)
    95→            ->where('siswa_id', $student->id)
    96→            ->where('status', 'berlangsung')
    97→            ->firstOrFail();
    98→
    99→        $jawabanSiswa = $request->input('jawaban', []);
   100→        $soalList     = $tryout->soal()->get();
   101→
   102→        $benar = 0; $salah = 0; $tidakDijawab = 0; $totalPoin = 0; $maxPoin = 0;
   103→
   104→        foreach ($soalList as $s) {
   105→            $maxPoin += (float) $s->poin;
   106→            $jawab    = $jawabanSiswa[$s->id] ?? null;
   107→
   108→            if ($jawab === null || $jawab === '') {
   109→                $tidakDijawab++;
   110→            } else {
   111→                $kunci = $s->kunci_jawaban;
   112→                if ($kunci !== null && $kunci !== '' && (string) $jawab === (string) $kunci) {
   113→                    $benar++;
   114→                    $totalPoin += (float) $s->poin;
   115→                } else {
   116→                    $salah++;
   117→                }
   118→            }
   119→        }
   120→
   121→        $totalSoal = $soalList->count();
   122→        $nilai     = $maxPoin > 0 ? ($totalPoin / $maxPoin) * 100 : ($totalSoal > 0 ? ($benar / $totalSoal) * 100 : 0);
   123→
   124→        $attempt->update([
   125→            'waktu_selesai'  => now(),
   126→            'nilai'          => round($nilai, 2),
   127→            'jawaban_benar'  => $benar,
   128→            'jawaban_salah'  => $salah,
   129→            'tidak_dijawab'  => $tidakDijawab,
   130→            'status'         => 'selesai',
   131→            'jawaban'        => $jawabanSiswa,
   132→        ]);
   133→
   134→        return redirect()->route('siswa.tryout.result', [$tryout->id, $attempt->id]);
   135→    }
